// Generated by esquadro: do not edit. A filter by a range of an amount
// (price_min, price_max), typed in money fields, with shadcn/ui's Popover.
import { Banknote, X } from "../icons.gen.ts"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { capitalize, t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"
import { formatMoney, MoneyInput } from "./money.tsx"
import type { Money } from "./money.tsx"

/** What the filter reads: "from R$ 10,00", "R$ 10,00 – R$ 50,00". */
function summary(min?: string, max?: string): string {
  const f = (a: string) => formatMoney({ amount: a })
  if (min && max) return `${f(min)} – ${f(max)}`
  if (min) return `${t("from")} ${f(min)}`
  if (max) return `${t("upTo")} ${f(max)}`
  return t("all")
}

export function MoneyRangeFilter({
  field,
  min,
  max,
  onChange,
}: {
  field: FieldMeta
  min?: string
  max?: string
  onChange: (min?: string, max?: string) => void
}) {
  const [open, setOpen] = useState(false)
  const [from, setFrom] = useState<Money | null>(null)
  const [to, setTo] = useState<Money | null>(null)
  const active = min !== undefined || max !== undefined
  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        if (o) {
          setFrom(min ? { amount: min } : null)
          setTo(max ? { amount: max } : null)
        }
        setOpen(o)
      }}
    >
      <PopoverTrigger asChild>
        <Button variant="outline" className={cn("h-10 gap-2 font-semibold", active && "border-primary text-primary")}>
          <Banknote />
          <span className="text-muted-foreground">{field.label}:</span>
          {summary(min, max)}
          {active && (
            <span
              role="button"
              tabIndex={0}
              aria-label={t("clearFilters")}
              className="-mr-1 rounded p-0.5 hover:bg-muted"
              onClick={(e) => {
                e.stopPropagation()
                onChange(undefined, undefined)
              }}
            >
              <X className="size-3.5" />
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-72">
        <form
          className="flex flex-col gap-3"
          onSubmit={(e) => {
            e.preventDefault()
            onChange(from?.amount, to?.amount)
            setOpen(false)
          }}
        >
          <div className="grid gap-1.5">
            <Label htmlFor={`${field.name}-min`}>{capitalize(t("from"))}</Label>
            <MoneyInput id={`${field.name}-min`} value={from} onChange={setFrom} negative={field.min === undefined || field.min < 0} />
          </div>
          <div className="grid gap-1.5">
            <Label htmlFor={`${field.name}-max`}>{capitalize(t("upTo"))}</Label>
            <MoneyInput id={`${field.name}-max`} value={to} onChange={setTo} negative={field.min === undefined || field.min < 0} />
          </div>
          <Button type="submit">{t("apply")}</Button>
        </form>
      </PopoverContent>
    </Popover>
  )
}

